#!/usr/bin/env node
/**
 * Generate every host-facing view of personas/ from personas/ itself.
 *
 * personas/ is the single source. The MCP server reads it directly, so the generated
 * files below are convenience surfaces -- a host that ignores them still gets correct
 * prompts. What this script buys is that the roster in SKILL.md, the Claude Code subagent
 * files and the human-readable table cannot silently drift from the personas the server
 * actually loads.
 *
 *   node scripts/sync-personas.mjs           write the generated files
 *   node scripts/sync-personas.mjs --check   fail with a diff if anything is stale
 */
import { readFileSync, writeFileSync, mkdirSync, rmSync, existsSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join, dirname } from "node:path";
import { loadPersonas, personaTitle } from "../mcp/lib/personas/registry.mjs";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const repo = (...parts) => join(ROOT, ...parts);
const BANNER = "<!-- GENERATED by scripts/sync-personas.mjs from personas/. Do not edit. -->";

const MODEL_BY_TIER = {
  fast: "haiku",
  standard: "sonnet",
  deep: "opus",
};

const reg = loadPersonas();
const analysts = reg.ids("analyst").map((id) => reg.get(id));
const debate = reg.ids("debate").map((id) => reg.get(id));
const masters = reg.ids("master").map((id) => reg.get(id));

// ---- generated content -----------------------------------------------------

function skillRosterBlock() {
  return [...analysts, ...debate].map((p) => `   - \`${p.id}\``).join("\n");
}

function personasDoc() {
  const rows = reg.all()
    .sort((a, b) => a.kind.localeCompare(b.kind) || a.order - b.order || a.id.localeCompare(b.id))
    .map((p) => {
      const attribution = p.source ? `${p.source.name} (${p.source.license})` : "original";
      return `| \`${p.id}\` | ${p.kind} | ${p.enabled ? "yes" : "no"} | ${p.rosters.join(", ") || "-"} | ${p.model_tier} | ${personaTitle(p, "English")} | ${(p.tags || []).join(", ") || "-"} | ${attribution} |`;
    });
  return [
    BANNER,
    "",
    "# Persona roster",
    "",
    "Every prompt this plugin sends is defined by a file under `personas/`. The MCP server",
    "loads that directory at startup; this table is generated from the same source.",
    "",
    "To add a role, add one file. It appears in the tool schema automatically.",
    "",
    "| id | kind | enabled | rosters | model tier | title | tags | provenance |",
    "|---|---|---|---|---|---|---|---|",
    ...rows,
    "",
    `Totals: ${analysts.length} evidence analysts, ${debate.length} debate roles, ${masters.length} masters, ${reg.all().length} files.`,
    "",
    "## Provenance",
    "",
    "Personas marked with an upstream project adapt its structure; the wording is original.",
    "See `docs/attribution.md` for full licence text.",
    "",
  ].join("\n");
}

/** Claude Code subagent files. OpenCode does not read .claude/agents/; that is Phase 2. */
function claudeAgentFiles() {
  const files = {};
  for (const persona of [...analysts, ...debate]) {
    const title = personaTitle(persona, "English");
    const body = persona.bodies[persona.default_lang] || "";
    const tools = persona.tools_hint?.length
      ? persona.tools_hint.map((t) => ({ websearch: "WebSearch", webfetch: "WebFetch" }[t] || t)).join(", ")
      : null;
    const frontmatter = [
      "---",
      `name: alphacouncil-${persona.id}`,
      `description: ${JSON.stringify(`${title} for AlphaCouncil equity research. ${(persona.tags || []).join(", ")}`)}`,
      `model: ${MODEL_BY_TIER[persona.model_tier] || "sonnet"}`,
      ...(tools ? [`tools: ${tools}`] : []),
      "---",
    ].join("\n");
    files[`.claude/agents/alphacouncil-${persona.id}.md`] = `${frontmatter}\n\n${BANNER}\n\n${body}\n`;
  }
  return files;
}

function replaceRegion(text, name, replacement) {
  const start = `<!-- generated:${name} start -->`;
  const end = `<!-- generated:${name} end -->`;
  const a = text.indexOf(start);
  const b = text.indexOf(end);
  if (a === -1 || b === -1) throw new Error(`missing generated:${name} markers`);
  return `${text.slice(0, a + start.length)}\n${replacement}\n${text.slice(b)}`;
}

function buildOutputs() {
  const outputs = { ...claudeAgentFiles() };
  outputs["docs/personas.md"] = personasDoc();
  outputs["skills/alphacouncil-agent/SKILL.md"] = replaceRegion(
    readFileSync(repo("skills/alphacouncil-agent/SKILL.md"), "utf8"),
    "roster",
    skillRosterBlock(),
  );
  return outputs;
}

// ---- write / check ---------------------------------------------------------

const outputs = buildOutputs();
const check = process.argv.includes("--check");
const stale = [];

for (const [rel, content] of Object.entries(outputs)) {
  const path = repo(rel);
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (current === content) continue;
  if (check) {
    stale.push({ rel, current, content });
    continue;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log(`wrote ${rel}`);
}

// A persona deleted from personas/ must not leave an orphan agent file behind.
const agentDir = repo(".claude/agents");
const expected = new Set(Object.keys(outputs).filter((f) => f.startsWith(".claude/agents/")).map((f) => f.split("/").pop()));
if (existsSync(agentDir)) {
  for (const file of readdirSync(agentDir)) {
    if (!file.startsWith("alphacouncil-") || expected.has(file)) continue;
    if (check) stale.push({ rel: `.claude/agents/${file}`, current: "(present)", content: "(should be deleted)" });
    else {
      rmSync(join(agentDir, file));
      console.log(`removed orphan .claude/agents/${file}`);
    }
  }
}

if (check) {
  if (stale.length === 0) {
    console.log(`sync-personas: ${Object.keys(outputs).length} generated files are up to date`);
    process.exit(0);
  }
  console.error("sync-personas --check: generated files are stale. Run `node scripts/sync-personas.mjs`.\n");
  for (const { rel, current, content } of stale) {
    console.error(`--- ${rel}`);
    const a = String(current ?? "(missing)").split("\n");
    const b = String(content).split("\n");
    let shown = 0;
    for (let i = 0; i < Math.max(a.length, b.length) && shown < 12; i += 1) {
      if (a[i] === b[i]) continue;
      console.error(`  ${i + 1}- ${a[i] ?? ""}`);
      console.error(`  ${i + 1}+ ${b[i] ?? ""}`);
      shown += 1;
    }
    console.error("");
  }
  process.exit(1);
}
